npm install resend 2>&1 | tail -3
mkdir -p src/lib
cat > src/lib/email.ts <<'EOF'
import { Resend } from "resend";

let client: Resend | undefined;

function getClient(): Resend {
  const key = process.env.RESEND_API_KEY;
  if (!key) throw new Error("RESEND_API_KEY is not set");
  return (client ??= new Resend(key));
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

type Message = { to: string; subject: string; html: string; text: string };

// Email must never break the request that triggered it: failures are logged, not thrown.
async function send({ to, subject, html, text }: Message): Promise<boolean> {
  try {
    const { error } = await getClient().emails.send({
      from: process.env.RESEND_FROM_EMAIL ?? "onboarding@resend.dev",
      to,
      subject,
      html,
      text,
    });
    if (error) {
      console.error(`[email] "${subject}" to ${to} refused: ${error.name}: ${error.message}`);
      return false;
    }
    return true;
  } catch (err) {
    console.error(`[email] "${subject}" to ${to} failed:`, err);
    return false;
  }
}

export function sendWelcomeEmail(user: { email: string; name: string }) {
  const name = escapeHtml(user.name);
  return send({
    to: user.email,
    subject: "Welcome to Notely",
    html: `<p>Hi ${name},</p><p>Welcome to Notely! Your account is ready.</p>`,
    text: `Hi ${user.name},\n\nWelcome to Notely! Your account is ready.`,
  });
}

export function sendPasswordResetEmail(
  user: { email: string; name: string },
  resetUrl: string,
) {
  const name = escapeHtml(user.name);
  const url = escapeHtml(resetUrl);
  return send({
    to: user.email,
    subject: "Reset your Notely password",
    html: `<p>Hi ${name},</p><p><a href="${url}">Reset your password</a>. The link expires in 1 hour.</p><p>If you didn't ask for this, you can ignore this email.</p>`,
    text: `Hi ${user.name},\n\nReset your password: ${resetUrl}\nThe link expires in 1 hour.\n\nIf you didn't ask for this, ignore this email.`,
  });
}
EOF
